SourceCode.Declaration:
class NVHcmSyncGradeWisePayroll extends RunBaseBatch implements BatchRetryable
{
    #NVHcmEmailAlertsMacro
}

Method.Source:
public Object dialog()
{
    DialogRunbase dialog = super();

    return dialog;
}

public void run()
{
    TransDate curDate = systemDateGet();
    TransDateTime curDateTime = DateTimeUtil::getSystemDateTime();//DateTimeUtil::newDateTime(curDate, 0);
    HcmPositionDetail positionDetail;
    HcmWorker worker;
    HcmPositionWorkerAssignment workerPosition;
    NVHcmCompensationLevelPayroll gradePayroll;

    while select worker
        join workerPosition 
            where workerPosition.Worker == worker.RecId
                && workerPosition.ValidFrom <= curDateTime
                && workerPosition.ValidTo >= curDateTime
        join positionDetail
            where positionDetail.Position == workerPosition.Position
                && positionDetail.ValidFrom <= curDateTime
                && positionDetail.ValidTo >= curDateTime
        join gradePayroll
            where gradePayroll.CompensationLevelId == positionDetail.NVLegalGrade
                && gradePayroll.PayrollEarningCodeId != ''
                && gradePayroll.FromDate <= curDate
                && gradePayroll.ToDate >= curDate

    {
        ttsbegin;
        PayrollEarningCode earningCode = PayrollEarningCode::findByEarningCode(gradePayroll.PayrollEarningCodeId);
        PayrollWorkerPositionEarningCode workerPositionEarningCode;

        select workerPositionEarningCode
            where workerPositionEarningCode.Worker == worker.RecId
                && workerPositionEarningCode.Position == positionDetail.Position
                && workerPositionEarningCode.EarningCode == earningCode.RecId
                && workerPositionEarningCode.ValidFrom <= curDate
                && workerPositionEarningCode.ValidTo >= curDate;

        if(workerPositionEarningCode)
        {
            if(workerPositionEarningCode.Formula != gradePayroll.SalaryAmount)
            {
                workerPositionEarningCode.selectForUpdate(true);
                workerPositionEarningCode.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
                workerPositionEarningCode.Formula = gradePayroll.SalaryAmount;

                workerPositionEarningCode.update();
            }
        }
        else
        {
            workerPositionEarningCode.Formula = gradePayroll.SalaryAmount;
            workerPositionEarningCode.EarningCode = earningCode.RecId;
            workerPositionEarningCode.modifiedField(fieldNum(PayrollWorkerPositionEarningCode, EarningCode));
            workerPositionEarningCode.Position = positionDetail.Position;
            workerPositionEarningCode.Worker = worker.RecId;
            workerPositionEarningCode.ValidFrom = gradePayroll.FromDate;
            workerPositionEarningCode.ValidTo = gradePayroll.ToDate;

            workerPositionEarningCode.insert();
        }
        ttscommit;
    }
}

static NVHcmSyncGradeWisePayroll construct()
{
    return new NVHcmSyncGradeWisePayroll();
}

static ClassDescription description()
{
    return "Payroll grade wise synchronize";
}

static void main(Args args)
{
    NVHcmSyncGradeWisePayroll job;

    job = NVHcmSyncGradeWisePayroll::construct();

    if(job.prompt())
        job.runOperation();
}

[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
